import assert from 'node:assert/strict';
import {configurationBcEffectsApi as effects} from './verification-runtime/dist/src/configuration-bc-effects-api.js';
import {configurationBcEffectsDependencies as pins,configurationBcEffectsAllLayouts} from './verification-runtime/dist/src/configuration-bc-effects.js';
import {configurationBcNativeReadApi,configurationBcNativeLayouts} from './verification-runtime/dist/src/configuration-bc-native-api.js';
import {configurationBcPreviewApi} from './verification-runtime/dist/src/configuration-bc-preview-api.js';
import {configurationBcRouteApi,configurationBcRouteLayouts} from './verification-runtime/dist/src/configuration-bc-route-api.js';
import {configurationBcGuardApi,configurationBcGuardLayouts} from './verification-runtime/dist/src/configuration-bc-guard-api.js';
import {configurationBcCtsApi} from './verification-runtime/dist/src/configuration-bc-cts-api.js';
import {configurationBcStateApi} from './verification-runtime/dist/src/configuration-bc-state-api.js';
import {configurationBcNativeTypes} from './verification-runtime/dist/src/configuration-bc-native-types.js';
import {configurationBcSetLayouts,configurationBcSetDomains,configurationBcSetFields} from './verification-runtime/dist/src/configuration-bc-set.js';
import {configurationBcPreviewFunctions,configurationBcPreviewStructures,configurationBcPreviewIncludes} from './verification-runtime/dist/src/configuration-bc-preview-pins.js';
import {configurationBcRouteIncludes} from './verification-runtime/dist/src/configuration-bc-route.js';
export const observations=[configurationBcNativeReadApi,configurationBcPreviewApi,configurationBcRouteApi,configurationBcGuardApi,configurationBcCtsApi];
const apis=[...observations,configurationBcStateApi,effects];
const layouts={...configurationBcNativeLayouts,...configurationBcRouteLayouts,...configurationBcGuardLayouts};
const tables=new Set([...Object.keys(configurationBcEffectsAllLayouts),...Object.keys(configurationBcRouteLayouts),...Object.keys(configurationBcNativeLayouts),...Object.keys(configurationBcSetLayouts)]);
const definitions=new Set([...apis.map(a=>a.functionName),...Object.keys(pins),...Object.keys(configurationBcPreviewFunctions),'RFC_READ_TABLE']);
const types=new Set(Object.values(configurationBcNativeTypes).map(t=>(t.kind==='domain'?'READ_DOMAIN':'READ_DATA_ELEMENT')+':'+t.name));
for(const name of Object.keys(configurationBcSetDomains))types.add('READ_DOMAIN:'+name);
for(const name of Object.keys(configurationBcPreviewStructures))types.add('READ_STRUCTURE:'+name);
const sourceUris=new Set([...Object.values(configurationBcPreviewIncludes),...Object.values(configurationBcRouteIncludes)].map(p=>p.sourceUri));
const sourceReads=[];
for(const [table,fields] of Object.entries(configurationBcSetFields)){
 const maximum=table==='SCPRATTR'?1:table==='SCPRPPRL'?32:table==='SCPRRECA'?50:100;
 const filters=[{ID:'EHS_CUNI_KNM',VERSION:'N'}];
 if(!['SCPRATTR','SCPRPPRL'].includes(table)){
  if(table!=='SCPRRECA')filters.length=0;
  for(const target of ['T006','T006A','T006B','T006C','T006D'])filters.push({ID:'EHS_CUNI_KNM',VERSION:'N',TABLENAME:target});
 }
 for(const filter of filters){const conditions=Object.entries(filter).map(([n,v])=>`${n} = '${v}'`);sourceReads.push({sql:`SELECT ${fields.join(', ')} FROM ${table} WHERE ${conditions.join(' AND ')}`,maximum:maximum+1,
 request:{functionName:'RFC_READ_TABLE',inputParameters:{QUERY_TABLE:table,DELIMITER:'|',NO_DATA:'',ROWSKIPS:'0',ROWCOUNT:String(maximum+1),OPTIONS:conditions.map((v,i)=>({TEXT:(i?'AND ':'')+v})),FIELDS:fields.map(FIELDNAME=>({FIELDNAME})),DATA:[]},outputParameters:[{name:'FIELDS',kind:'table',fields:['FIELDNAME']},{name:'DATA',kind:'table',fields:['WA']}]}});}
}
export const outputs=a=>[...a.exportParameters.map(p=>({name:p.name,kind:'scalar'})),...(a.tableParameters??[]).map(p=>({name:p.name,kind:'table',fields:[...layouts[p.typeName].fields]}))];
export const refusedInputs={IV_BC_SET:'OTHER',IV_VERSION:'A',IV_TASK:'GR2K923492',IV_CTS_VERSION:'f'.repeat(64)};
export function guardEffectsBackend(backend,metrics,save,verify){
 const remote=backend.callRemoteFunction.bind(backend),repo=backend.callSapRepository.bind(backend),ddic=backend.callSapDdic.bind(backend),query=backend.runQuery?.bind(backend),source=backend.readSourceByUri?.bind(backend);
 let fixed,probe=false;
 backend.callRemoteFunction=async(id,r)=>{
  assert.equal(id,'w200');await verify();const p=r.inputParameters;
  if(r.functionName==='RFC_READ_TABLE'){
   assert(sourceReads.some(v=>JSON.stringify(v.request)===JSON.stringify(r)),'Unapproved source-table read');
   metrics.sourceTableReads=(metrics.sourceTableReads??0)+1;assert(metrics.sourceTableReads<=3840);await save();return remote(id,r);
  }
  const a=apis.find(a=>a.functionName===r.functionName);assert(a,'Unapproved RFC');
  assert.deepEqual(r.outputParameters,outputs(a));
  assert.deepEqual(Object.keys(p).sort(),[...a.importParameters,...(a.tableParameters??[])].map(p=>p.name).sort());
  if(a===effects){
   assert(fixed,'Server-owned CTS binding not established');
   if(probe){const fields=Object.keys(fixed).filter(k=>p[k]!==fixed[k]);assert.equal(fields.length,1);assert.equal(p[fields[0]],refusedInputs[fields[0]]);assert(metrics.nativeRefusals<4);metrics.nativeRefusals++;}
   else{assert.deepEqual(p,fixed);assert(metrics.normalCalls<2);metrics.normalCalls++;}
  }else{
   assert.equal(p.IV_BC_SET,'EHS_CUNI_KNM');assert.equal(p.IV_VERSION,'N');
   for(const parameter of a.importParameters)if(parameter.name.endsWith('_VERSION')&&parameter.name!=='IV_VERSION')assert.match(p[parameter.name],/^[a-f0-9]{64}$/);
   for(const parameter of a.tableParameters??[])assert.deepEqual(p[parameter.name],[]);
   if([configurationBcCtsApi,configurationBcStateApi].includes(a)){assert.equal(p.IV_REQUEST,'GR2K923429');assert.equal(p.IV_TASK,'GR2K923430');}
   const n=metrics.observations[a.functionName]??0;
   // Two complete preflights compose 32 native READs each, plus bracket observations.
   assert(n<(a===configurationBcStateApi?2:a===configurationBcNativeReadApi?68:32),'Readonly observation budget exhausted');metrics.observations[a.functionName]=n+1;
  }
  await save();return remote(id,r);
 };
 backend.callSapRepository=async(id,r)=>{
  assert.equal(id,'w200');assert.deepEqual(Object.keys(r).sort(),['objectName','objectType','operation']);
  assert.equal(r.operation,'READ_FUNCTION_INTERFACE');assert.equal(r.objectType,'SRC1');assert(definitions.has(r.objectName),'Unapproved definition');
  metrics.definitionReads++;await save();return repo(id,r);
 };
 backend.callSapDdic=async(id,r)=>{
  assert.equal(id,'w200');assert.deepEqual(Object.keys(r).sort(),['objectName','operation']);
  assert(r.operation==='READ_TRANSPARENT_TABLE'?tables.has(r.objectName):types.has(r.operation+':'+r.objectName),'Unapproved DDIC');
  metrics.ddicReads++;await save();return ddic(id,r);
 };
 backend.runQuery=async(id,sql,maximum)=>{assert.equal(id,'w200');await verify();assert(sourceReads.some(v=>v.sql===sql&&v.maximum===maximum),'Unapproved source query');metrics.sourceQueries=(metrics.sourceQueries??0)+1;assert(metrics.sourceQueries<=3840);await save();assert(query);return query(id,sql,maximum);};
 backend.readSourceByUri=async(id,uri)=>{assert.equal(id,'w200');await verify();assert(sourceUris.has(uri),'Unapproved policy source');metrics.policySourceReads=(metrics.policySourceReads??0)+1;await save();assert(source);return source(id,uri);};
 for(const name of ['callSapHelper','callSapTransport','callSapDebug','writeSource','activate','createObject','deleteObject','deleteAbapObject','callSapDynpro'])backend[name]=async()=>assert.fail('Forbidden backend operation: '+name);
 return {
  bind(state){assert(!fixed);assert.equal(state.system,'GR2');assert.equal(state.client,'200');assert.equal(state.user,'WYS');assert.match(state.versions.cts,/^[a-f0-9]{64}$/);fixed={IV_BC_SET:'EHS_CUNI_KNM',IV_VERSION:'N',IV_REQUEST:'GR2K923429',IV_TASK:'GR2K923430',IV_CTS_VERSION:state.versions.cts};return {...fixed};},
  probes(value){probe=value;}
 };
}
